using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.IO;

var build = BinaryLog.ReadBuild(args[0]);

// Get the embedded files from the binlog archive
var archives = build.FindChildrenRecursive<ArchiveFile>();
Console.WriteLine($"Found {archives.Count()} archive files");
foreach (var a in archives)
{
    if (a.Name.EndsWith(".cs") || a.Name.EndsWith(".csproj") || a.Name.EndsWith(".sln"))
    {
        Console.WriteLine($"\n=== {a.Name} ===");
        Console.WriteLine(a.GetType().GetProperties().Select(p => $"{p.Name}").Aggregate((a,b) => $"{a}, {b}"));

        // Try SourceText property
        try {
            var textProp = a.GetType().GetProperty("SourceText");
            if (textProp != null) Console.WriteLine(textProp.GetValue(a));
        } catch {}

        // Try Text property
        try {
            var textProp = a.GetType().GetProperty("Text");
            if (textProp != null) Console.WriteLine(textProp.GetValue(a));
        } catch {}
    }
}

// Also look for the compiler CSC task
var tasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc");
foreach (var t in tasks)
{
    Console.WriteLine($"\nCSC Task in project: {t.Parent?.GetType().Name}");
    var folders = t.FindChildrenRecursive<Folder>();
    foreach (var f in folders)
    {
        Console.WriteLine($"  Folder: {f.Name}");
    }
}
