using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Get source files from the embedded archive
if (build.SourceFiles != null)
{
    Console.WriteLine($"Found {build.SourceFiles.Count} source files in archive");
    foreach (var kvp in build.SourceFiles)
    {
        if (kvp.Key.EndsWith(".cs") && !kvp.Key.Contains("obj/"))
        {
            Console.WriteLine($"\n=== {kvp.Key} ===");
            Console.WriteLine(kvp.Value);
        }
    }
}
else
{
    Console.WriteLine("No source files archive found");
}

// Also dump full error details with all context
Console.WriteLine("\n\n=== FULL ERROR ANALYSIS ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    Console.WriteLine($"\nError: [{e.Code}] {e.Text}");
    Console.WriteLine($"  File: {e.File}:{e.LineNumber}:{e.ColumnNumber}");

    // Walk up to find project
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p)
        {
            Console.WriteLine($"  Project: {p.Name} (Source: {p.SourceFilePath})");
            break;
        }
        node = node.Parent;
    }
}

// Check project dependency graph
Console.WriteLine("\n\n=== PROJECT BUILD ORDER ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"Project: {p.Name} - Succeeded: {p.Succeeded}");
}
